<?php
declare(strict_types=1); session_start(); require_once __DIR__ . '/../config.php'; if(($_SESSION['admin_role']??'')!=='admin'){header('Location: admin-login.php');exit;} $pdo=db(); $stats=['products'=>$pdo->query("SELECT COUNT(*) FROM products")->fetchColumn(),'customers'=>$pdo->query("SELECT COUNT(*) FROM users WHERE role='customer'")->fetchColumn(),'orders'=>$pdo->query("SELECT COUNT(*) FROM orders")->fetchColumn(),'revenue'=>$pdo->query("SELECT COALESCE(SUM(total_amount),0) FROM orders WHERE status <> 'cancelled'")->fetchColumn()]; function rep(mixed $v):string{return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');} ?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Reports</title><style>body{margin:0;background:#f4f8f6;font-family:Arial;color:#14201d}.bar{padding:18px 5%;background:#10231e;color:#fff;display:flex;justify-content:space-between}.bar a{color:#fff}.page{max-width:1100px;margin:30px auto;padding:0 18px}.grid{display:grid;grid-template-columns:repeat(4,1fr);gap:16px}.card{background:#fff;border-radius:16px;padding:25px;box-shadow:0 12px 30px #1232;animation:up .5s ease both}.value{font-size:30px;font-weight:900;color:#087f63}@keyframes up{from{opacity:0;transform:translateY(12px)}to{opacity:1;transform:none}}@media(max-width:700px){.grid{grid-template-columns:repeat(2,1fr)}}</style></head><body><header class="bar"><strong>Reports</strong><a href="admin-dashboard.php">Dashboard</a></header><main class="page"><h1>Business overview</h1><div class="grid"><?php foreach(['products'=>'Products','customers'=>'Customers','orders'=>'Orders','revenue'=>'Revenue'] as $key=>$label): ?><div class="card"><div><?=rep($label)?></div><div class="value"><?= $key==='revenue'?'৳ '.number_format((float)$stats[$key],2):number_format((int)$stats[$key]) ?></div></div><?php endforeach; ?></div></main></body></html>
